# sdoh_label_incremental.py
import csv
import os
import time
from typing import List, Set, Dict
from tqdm import tqdm

from openai import OpenAI

# Input: 5000-comment sample generated by sample_5000_comments.py
CSV_SAMPLE_INPUT = "sample_5000.csv"

# Output: labeled comments (can be appended to across runs)
CSV_OUTPUT = "gpt_sdoh_label_5000.csv"

REC_COL = "rec"
COMMENT_COL_INPUT = "Comment"   # column name in the sample file
OUTPUT_COMMENT_COL = "Comment"  # column name in the output file
OUTPUT_LABEL_COL = "gpt_label"

client = OpenAI(api_key=(os.getenv("OPENAI_API_KEY")).strip() or None)

ALLOWED_LABELS: List[str] = [
    "financial-constraint",
    "living-condition",
    "transportation",
    "education",
    "employment-status",
    "social-connection",
    "violence-abuse",
    "disability-status",
    "physical-activity",
    "substance-use",
    "sexual-activity",
    "discrimination",
    "no_sdoh",
]


SYSTEM_PROMPT = """You are a strict multi-label classifier for Social Determinants of Health (SDOH).

You are shown patient commennt, and this comment is made by a patient after 
Goal:
- Identify labels only if the patient comment reveals underlying life circumstances or social factors
- These factors do not have to have direct impacts on health or current medical care, but should reflect ongoing social conditions affecting the patient's life
- DO NOT label issues that arise solely from current medical care, treatment, discharge instructions, surgery effects, temporary recovery, hospital processes, or wait times.

Allowed labels:
financial-constraint, living-condition, transportation, education, employment-status,
social-connection, violence-abuse, disability-status, physical-activity, substance-use,
sexual-activity, discrimination, no_sdoh

These are the definition for each label:

- financial-constraint: A state of limited, uncertain, or unstable access to sufficient financial resources to meet current and ongoing needs such as housing, food, utilities, and medical care.
- living-condition: Circumstances related to the safety, stability, adequacy, and affordability of one's housing and surrounding environment, including experiences of housing instability, homelessness, or inadequate housing.
- transportation: Uncertain, limited, or no access to safe, reliable, accessible, affordable, and socially acceptable means of transportation necessary to maintain health, well-being, or livelihood.
- education: The attainment of formal education and literacy skills necessary for employment, health decision-making, and daily functioning, including having less than a high school education or limited health literacy.
- employment-status: Access to stable, safe, and adequate employment that provides sufficient income and benefits; retired status is included only when it affects financial stability.
- social-connection: The structural, functional, and quality aspects of an individual's social interactions—including social networks, support, isolation, perceived loneliness, and barriers such as language limitations.
- violence-abuse: Exposure to physical, sexual, psychological, or financial harm, coercion, or neglect within relationships of trust or intimacy, including intimate partner violence or elder abuse.
- disability-status: A physical, sensory, cognitive, or mental impairment—including conditions such as significant pain, allergies, morbid obesity, or temporary wheelchair use—that limits daily functioning or participation in life activities.
- physical-activity: Engagement in bodily movement that contributes to maintaining or improving health, physical fitness, and overall well-being; insufficient activity may increase risk for chronic disease and reduced quality of life. 
- substance-use: The use of alcohol, tobacco, prescription medications, or illicit substances in a manner that may negatively impact health, functioning, or social well-being.
- discrimination: Differences in access to resources, opportunities, or care based on personal characteristics such as age, sex, gender identity, sexual orientation, race, ethnicity, or other identity factors.

Instructions:
- Output one or more labels from the allowed list, separated by commas with no extra words.
- If none apply, output: no_sdoh
- Do not invent labels. Do not add explanations. Only return labels.


Examples (format only; content varies):
- "I can't afford my medication." -> financial-constraint
- "It's a very long 2-hour bus ride to the hospital." -> transportation
- "After surgery I couldn't drive for 3 days." -> no_sdoh
"""



def clean_labels(text: str, allowed: Set[str]) -> str:
    """
    Keep only allowed labels; normalize commas/whitespace; default to no_sdoh if none.
    """
    if not text:
        return "no_sdoh"
    raw = [t.strip().lower() for t in text.split(",")]
    kept = [t for t in raw if t in allowed]
    if not kept:
        return "no_sdoh"
    # de-duplicate while preserving order
    seen = set()
    dedup = []
    for t in kept:
        if t not in seen:
            seen.add(t)
            dedup.append(t)
    # if multiple and includes no_sdoh (contradiction), drop no_sdoh
    if len(dedup) > 1 and "no_sdoh" in dedup:
        dedup = [t for t in dedup if t != "no_sdoh"]
        if not dedup:
            dedup = ["no_sdoh"]
    return ",".join(dedup)


def classify_comment(comment: str, max_retries: int = 5, base_delay: float = 1.0) -> str:
    """
    Call Chat Completions with temperature=0 for deterministic behavior and retry on transient errors.
    """
    if not comment or not comment.strip():
        return "no_sdoh"

    last_err = None
    for attempt in range(max_retries):
        try:
            resp = client.chat.completions.create(
                model="gpt-5",
                messages=[
                    {"role": "system", "content": SYSTEM_PROMPT},
                    {"role": "user", "content": comment.strip()},
                ],
            )
            raw = resp.choices[0].message.content.strip()
            cleaned = clean_labels(raw, set(ALLOWED_LABELS))
            return cleaned
        except Exception as e:
            last_err = e
            print(f"    [classify][WARN] Error on attempt {attempt + 1}: {e}")
            # simple exponential backoff
            sleep_for = base_delay * (2 ** attempt)
            print(f"    [classify] Sleeping for {sleep_for:.1f}s before retry...")
            time.sleep(sleep_for)

    # If all retries fail, mark as no_sdoh and print an error for visibility
    print(f"    [classify][WARN] Failed to classify comment after {max_retries} attempts. "
          f"Last error: {last_err}")
    return "no_sdoh"


def load_existing_labels(path: str) -> Dict[str, str]:
    """
    Load existing labels from CSV_OUTPUT, mapping rec -> label.
    If the file does not exist, returns an empty dict.
    """
    if not os.path.exists(path):
        print(f"[INFO] No existing output file {path!r}. Starting fresh.")
        return {}

    print(f"[INFO] Loading existing labels from {path!r}...")
    existing: Dict[str, str] = {}
    with open(path, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rec_id = row.get(REC_COL)
            label = row.get(OUTPUT_LABEL_COL, "")
            if rec_id is not None and str(rec_id).strip() != "" and label:
                existing[str(rec_id).strip()] = label

    print(f"[INFO] Loaded {len(existing)} already-labeled comments.")
    return existing


def main():
    # Load sample of 5000 comments
    print(f"[INFO] Reading sample input from {CSV_SAMPLE_INPUT!r}...")
    with open(CSV_SAMPLE_INPUT, newline="", encoding="utf-8") as f_in:
        reader = csv.DictReader(f_in)
        sample_rows = list(reader)

    total_sample = len(sample_rows)
    print(f"[INFO] Loaded {total_sample} sampled comments.")

    if COMMENT_COL_INPUT not in (reader.fieldnames or []):
        raise ValueError(f"Sample CSV must contain a '{COMMENT_COL_INPUT}' column.")

    # Load existing labels (if any)
    existing_labels = load_existing_labels(CSV_OUTPUT)

    # Determine which rows still need labeling
    remaining_rows = []
    for row in sample_rows:
        rec_id = str(row.get(REC_COL, "")).strip()
        if not rec_id:
            # if something is wrong and rec is missing, skip row
            continue
        if rec_id not in existing_labels:
            remaining_rows.append(row)

    num_remaining = len(remaining_rows)
    print(f"[INFO] {num_remaining} comments remaining to label "
          f"(out of {total_sample}).")

    if num_remaining == 0:
        print("[DONE] All comments in the sample have already been labeled.")
        return

    # Prepare output file (append if exists, write header only if new)
    file_exists = os.path.exists(CSV_OUTPUT)
    f_out = open(CSV_OUTPUT, "a", newline="", encoding="utf-8")
    writer = csv.DictWriter(f_out, fieldnames=[REC_COL, OUTPUT_COMMENT_COL, OUTPUT_LABEL_COL])

    if not file_exists:
        writer.writeheader()

    try:
        for row in tqdm(remaining_rows, total=num_remaining, desc="Labeling", unit="comment"):
            rec_id = str(row.get(REC_COL, "")).strip()
            comment = (row.get(COMMENT_COL_INPUT, "") or "").strip()

            label = classify_comment(comment)

            writer.writerow({
                REC_COL: rec_id,
                OUTPUT_COMMENT_COL: comment,
                OUTPUT_LABEL_COL: label,
            })
            # Flush so that progress is saved even if you Ctrl+C mid-run
            f_out.flush()
    finally:
        f_out.close()

    print(f"[DONE] Labeled {num_remaining} new comments. "
          f"Output written/updated in {CSV_OUTPUT!r}.")


if __name__ == "__main__":
    main()
